<script setup>
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {Button,ErrorBox,Field,Notice,Modal,PageHeader} from '../ui/index.js';
import {createWorkflowExtensionStore} from './extensions-store.js';
import {ADAPTER_EXAMPLE,runAdapter} from './extension-adapter.js';
const props=defineProps({store:Object,readOnly:Boolean});
const emit=defineEmits(['dirty-state']);
const catalog=props.store||createWorkflowExtensionStore(),search=ref(''),source=ref(''),draft=ref(null),editingId=ref(''),error=ref(null),preview=ref(null),busy=ref(false),sample=ref('');
const original=ref(''),discard=ref(false),editedHash=ref('');
const staleEdit=computed(()=>{if(!editingId.value||!draft.value)return '';const current=catalog.state.items.find(item=>item.id===editingId.value);return !current?'适配器已被删除，当前代码已保留，请关闭后重新打开有效定义。':current.content_sha256!==editedHash.value?'适配器已被其他成员更新，当前代码已保留供核对，请关闭后重新打开最新定义。':'';});
const dirty=computed(()=>!props.readOnly&&!!draft.value&&JSON.stringify(draft.value)!==original.value);
watch([dirty,busy,()=>catalog.state.updating],()=>emit('dirty-state',dirty.value||busy.value||!!catalog.state.updating));
function beforeUnload(event){if(dirty.value){event.preventDefault();event.returnValue='';}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload));
onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload));
const sourceLabel={jmeter:'JMeter 原生',platform:'平台自定义',project:'项目自定义',external:'外部自定义'};
const rows=computed(()=>catalog.state.items.filter(x=>(!source.value||x.source===source.value)&&[x.name,x.component,x.class_name,x.source_url].join(' ').toLowerCase().includes(search.value.toLowerCase())));
onMounted(()=>catalog.load());
function create(component=''){if(draft.value||busy.value)return;editingId.value='';editedHash.value='';draft.value={name:'',component:typeof component==='string'?component:'',version:'1.0.0',description:'',source_url:'',template_xml:'',code:ADAPTER_EXAMPLE};original.value=JSON.stringify(draft.value);sample.value='';preview.value=null;error.value=null;}
async function edit(item){if(draft.value||busy.value)return;busy.value=true;try{draft.value=JSON.parse(JSON.stringify(await catalog.ensureDefinition(item.id,{reload:true})));original.value=JSON.stringify(draft.value);editingId.value=item.id;editedHash.value=catalog.state.items.find(row=>row.id===item.id)?.content_sha256;preview.value=null;error.value=null;sample.value='';}catch(reason){error.value=reason;}finally{busy.value=false;}}
function close(){if(busy.value)return;if(dirty.value){discard.value=true;return;}draft.value=null;}
function discardDraft(){discard.value=false;draft.value=null;}
async function save(){if(props.readOnly||!draft.value||busy.value)return false;if(staleEdit.value){error.value=new Error(staleEdit.value);return false;}busy.value=true;error.value=null;try{const d={...draft.value};delete d.id;const saved=editingId.value?await catalog.updateDefinition(editingId.value,d):await catalog.createDefinition(d,true);if(saved){draft.value=null;discard.value=false;}return !!saved;}catch(reason){error.value=reason;}finally{busy.value=false;}}
async function test(){busy.value=true;error.value=null;preview.value=null;try{preview.value=await runAdapter(draft.value.code,draft.value.component,sample.value);}catch(reason){error.value=reason;}finally{busy.value=false;}}
const deleting=ref(null);
async function remove(){if(await catalog.deleteDefinition(deleting.value.id))deleting.value=null;}
defineExpose({hasUnsavedChanges:()=>dirty.value,isBusy:()=>busy.value||!!catalog.state.updating,saveChanges:save,hasOpenDraft:()=>!!draft.value,requestClose:close});
</script>
<template><section class="workflow-extension-manager"><PageHeader title="扩展管理" subtitle="查看 JMeter 组件来源，管理当前项目的画布适配器"><Button @click="catalog.load" :disabled="catalog.state.loading">刷新</Button><Button v-if="!readOnly" variant="primary" @click="create">新增 JavaScript 适配器</Button></PageHeader><Notice>原生组件由 Apache JMeter 5.6.3 提供；平台扩展随平台构建。项目适配器只定义画布编辑字段，组件运行仍使用 JMeter Java 类及对应依赖。</Notice><ErrorBox :error="catalog.state.error" :retry="catalog.load"/><ErrorBox :error="!draft&&error"/><div class="extension-filters"><input v-model="search" aria-label="搜索扩展" placeholder="搜索名称、组件类型或来源"/><select v-model="source" aria-label="扩展来源"><option value="">全部来源</option><option v-for="(label,key) in sourceLabel" :key="key" :value="key">{{ label }}</option></select><span>{{ rows.length }} 个扩展</span></div><div class="extension-table"><table><thead><tr><th>扩展 / 组件类型</th><th>来源</th><th>版本 / 画布适配</th><th>来源位置</th><th>操作</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><strong>{{ item.name }}</strong><code>{{ item.component }}</code><small v-if="item.description">{{ item.description }}</small></td><td><span class="extension-source" :data-source="item.source">{{ sourceLabel[item.source]||'未知来源' }}</span></td><td>{{ item.version||'随平台构建' }}<small>{{ item.adapter==='runtime'?'执行器注入':item.adapter==='javascript'?'JavaScript 适配器':'原生画布适配' }}</small><small v-if="item.source==='project'">{{ item.editor_enabled?'编辑已启用':'编辑未启用' }}</small><small>运行依赖：{{ item.runtime_status==='verified'?'已验证':'未验证' }}</small></td><td><span>{{ item.source_url||'未填写' }}</span></td><td><template v-if="item.source==='project'"><Button @click="edit(item)" :disabled="busy||!!catalog.state.updating">{{ readOnly?'查看':'编辑' }}</Button><template v-if="!readOnly"><Button :disabled="!!catalog.state.updating" @click="catalog.setInstalled(item.id,!item.editor_enabled)">{{ item.editor_enabled?'停用编辑':'启用编辑' }}</Button><Button variant="danger-outline" :disabled="!!catalog.state.updating" @click="deleting=item">删除</Button></template></template><span v-else>平台维护</span></td></tr></tbody></table></div>
<details class="extension-usage"><summary>当前流程引用的组件</summary><p>读取当前项目的已保存流程，统计画布及保留子流程中的组件类型和节点数量。</p><Button :disabled="catalog.state.usageLoading" @click="catalog.loadUsage">{{ catalog.state.usageLoading?'正在读取…':'读取组件引用' }}</Button><div v-if="catalog.state.usageLoaded" class="extension-table"><table><thead><tr><th>组件类型</th><th>来源</th><th>节点数 / 流程</th><th>画布适配</th></tr></thead><tbody><tr v-for="item in catalog.state.usage" :key="item.component"><td><strong>{{ item.name }}</strong><code>{{ item.component }}</code></td><td>{{ sourceLabel[item.source] }}</td><td>{{ item.node_count }}<small v-for="flow in item.workflows" :key="flow.id">{{ flow.name }} · v{{ flow.revision }}</small></td><td><Button v-if="item.source==='external'&&!readOnly" @click="create(item.component)">新增画布适配器</Button><span v-else>原生 / 平台适配</span></td></tr></tbody></table></div></details>
<Modal v-if="draft" :title="editingId?'画布适配器':'新增画布适配器'" wide @close="close"><form id="extension-form" @submit.prevent="save"><fieldset :disabled="busy||readOnly" class="extension-fields"><Field label="适配器名称" required><input v-model="draft.name" required maxlength="200"/></Field><Field label="JMeter 组件类型" required hint="填写 JMX 元素名或 Java 类名，须与导入组件完全一致。"><input v-model="draft.component" required maxlength="240"/></Field><Field label="版本" required><input v-model="draft.version" required/></Field><Field label="来源位置"><input v-model="draft.source_url" placeholder="源码仓库或维护文档地址"/></Field><Field label="说明"><textarea v-model="draft.description" rows="2"/></Field><Field label="组件 XML 模板" hint="可选，填写单个组件元素；提供模板后可从画布组件栏创建。"><textarea v-model="draft.template_xml" rows="4" spellcheck="false"/></Field><Field label="JavaScript 适配代码" required hint="定义 function adapt(component)，返回 {title, fields:[{property,label,kind,tag}]}。kind 为 text/code/boolean。"><textarea v-model="draft.code" required rows="15" spellcheck="false" class="extension-code"/></Field></fieldset><details><summary>本地预览</summary><Field label="样本属性 XML" hint="仅粘贴 stringProp 等属性片段，预览不保存、不执行 JMeter 请求。"><textarea v-model="sample" rows="4"/></Field><Button type="button" :disabled="busy" @click="test">运行适配预览</Button><pre v-if="preview">{{ JSON.stringify(preview,null,2) }}</pre></details><ErrorBox :error="staleEdit?new Error(staleEdit):error"/><ErrorBox :error="catalog.state.error"/></form><template #footer><Button :disabled="busy" @click="close">关闭</Button><Button v-if="!readOnly" type="submit" form="extension-form" variant="primary" :disabled="busy||!!catalog.state.updating||!!staleEdit">{{ busy?'正在保存…':'保存适配器' }}</Button></template></Modal>
<Modal v-if="discard" title="处理未保存的适配器" @close="discard=false"><p>适配代码尚未保存，关闭会丢失本次修改。</p><template #footer><Button @click="discard=false">继续编辑</Button><Button variant="danger-outline" @click="discardDraft">放弃修改并关闭</Button></template></Modal>
<Modal v-if="deleting" title="删除画布适配器" @close="deleting=null"><p>删除“{{ deleting.name }}”？已有流程配置和历史 XML 会保留，画布回退原始组件。</p><ErrorBox :error="catalog.state.error"/><template #footer><Button @click="deleting=null">取消</Button><Button variant="danger" :disabled="!!catalog.state.updating" @click="remove">删除</Button></template></Modal>
</section></template>
<style scoped>.workflow-extension-manager{display:grid;gap:16px;min-width:0}.extension-filters{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.extension-filters input{flex:1;min-width:180px}.extension-table{overflow:auto;border:1px solid var(--border);border-radius:10px}.extension-table table{width:100%;border-collapse:collapse;font-size:13px}.extension-table th,.extension-table td{padding:12px;text-align:left;border-bottom:1px solid var(--border);vertical-align:top}.extension-table th{background:var(--surface-alt)}.extension-table td{max-width:360px;overflow-wrap:anywhere}.extension-table code,.extension-table small{display:block;color:var(--muted);margin-top:5px}.extension-table td:last-child{white-space:nowrap}.extension-source{display:inline-block;padding:4px 8px;border-radius:6px;background:var(--accent-soft);color:var(--accent)}.extension-source[data-source=project]{background:var(--surface-alt)}.extension-fields{border:0;padding:0;display:grid;gap:14px;min-width:0}.extension-fields textarea{width:100%;box-sizing:border-box}.extension-code{font-family:monospace}.extension-fields input{width:100%;box-sizing:border-box}</style>
